    static class WordScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        WordScanner(InputStream in) {
            this.in = in;
        }

        private int read() {
            if (ptr == len) {
                try {
                    len = in.read(buffer, 0, buffer.length);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        String scan() {
            int c = read();
            while (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
                c = read();
            }
            if (c == -1) {
                return null;
            }
            StringBuilder sb = new StringBuilder();
            while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
